import{_ as n,C as s,o as r,c as o,a3 as t,E as i}from"./chunks/framework.BZKbe9n2.js";const f=JSON.parse('{"title":"Editing tags","description":"","frontmatter":{},"headers":[],"relativePath":"guide/editing.md","filePath":"guide/editing.md"}'),d={name:"guide/editing.md"};function l(h,e,g,c,m,u){const a=s("Screenshot");return r(),o("div",null,[e[0]||(e[0]=t('<h1 id="editing-tags" tabindex="-1">Editing tags <a class="header-anchor" href="#editing-tags" aria-label="Permalink to &quot;Editing tags&quot;">​</a></h1><p>Editors and admins can correct the information of the library: titles, artists, albums, years, genres, composers and more.</p><h2 id="edit-mode" tabindex="-1">Edit mode <a class="header-anchor" href="#edit-mode" aria-label="Permalink to &quot;Edit mode&quot;">​</a></h2><p>Switch the <strong>View</strong> from <strong>Listen</strong> to <strong>Edit</strong>. Tracks get checkboxes; select the tracks you want to change, or <strong>Select all</strong>, and choose <strong>Edit tags</strong>. On an album page, <strong>Edit album</strong> edits the album itself.</p>',4)),i(a,{name:"tag-editor",alt:"The tag editor for an album"}),e[1]||(e[1]=t('<ul><li>A field with <strong>different values</strong> among the selected tracks stays unchanged unless you enter a value.</li><li>Separate several values (for example genres) with commas.</li><li><strong>Title on this album</strong> and <strong>Artist on this album</strong> change how a track appears on this album only; the recording keeps its own title.</li></ul><p>Each field is stored where it belongs: a recording&#39;s title once for every album it appears on, the album&#39;s year once for the album. <strong>Apply tags</strong> saves the change; large changes run in the background.</p><p>From the search, <strong>Edit all results</strong> edits every result at once.</p><h2 id="undo-and-history" tabindex="-1">Undo and history <a class="header-anchor" href="#undo-and-history" aria-label="Permalink to &quot;Undo and history&quot;">​</a></h2><p><strong>Change history</strong> lists every change with who made it and when. Every change can be undone; fields changed again since then stay as they are and are reported.</p><h2 id="tags-in-the-files" tabindex="-1">Tags in the files <a class="header-anchor" href="#tags-in-the-files" aria-label="Permalink to &quot;Tags in the files&quot;">​</a></h2><p>Anthology keeps the information in its database and writes it into the files it manages. Files that stay in their folder (referenced) are only written if this was allowed during the import. Downloads and the music sent to speakers always carry the tags of their album.</p>',7))])}const _=n(d,[["render",l]]);export{f as __pageData,_ as default};
